"""Cross-model phase-3 report -> docs/phase3/CROSS_MODEL.md (SPEC_PHASE3 §8, all 4 models)."""
import pandas as pd

from audit.analysis.phase3_stats import (
    LEVELS,
    LEVEL_NAMES,
    abstention,
    cue_level_penalties,
    drift,
    gender_preference,
    manip_summary,
    placebo_decomposition,
)

MODELS = ["deepseek_v41_flash", "claude_haiku_55", "gpt6_luna", "qwen38_flash"]
SHORT = dict(zip(MODELS, ["DeepSeek", "Haiku", "Luna", "Qwen"]))

L = ["# Phase 3 — cross-model report (all four models)", "",
     "Generated by `uv run python -m audit.analysis.cross_model` from run logs;",
     "comparators as in the main report. Main-run numbers: docs/report/stats.json.", "",
     "## Validity", "",
     "| model | main valid | refusals | lawyer rerun |",
     "| --- | --- | --- | --- |",
     "| DeepSeek | 91,686/91,888 (99.78%) | 0 | 474/474 |",
     "| Haiku | 91,560/91,888 (99.64%) | 1,126 (analyzed as outcome) | 471/474 |",
     "| Luna | 91,315/91,888 (99.38%) | 0 | 474/474 |",
     "| Qwen | 89,514/91,888 (97.42%; strict-validity floor, repair recovered 5,926) | 0 | 460/474 |",
     "", "## Manipulation check (§2.2)", ""]
L.append(manip_summary().to_markdown(index=False))

L += ["", "## §8.2 Parent penalty by cue level — P(treatment chosen) vs the paired childless candidate",
      "", "Both genders pooled. Parity = .50.", ""]
rows = []
for m in MODELS:
    cl = cue_level_penalties(m)
    for con in ["parent", "parent_gap", "personal", "gap_travel", "gap_parental_only"]:
        r = {"model": SHORT[m], "contrast": con}
        for lvl in LEVELS:
            s = cl[(cl.contrast == con) & (cl.level == LEVEL_NAMES[lvl])]
            r[LEVEL_NAMES[lvl]] = round(float(s["P(parent)"].astype(float).mean()), 3) if len(s) else None
        rows.append(r)
L.append(pd.DataFrame(rows).pivot(index="contrast", columns="model").round(3).to_markdown())

L += ["", "## §8.3 Placebo decomposition (L0, mothers)", "",
      "parenthood = `parent` − `personal`; caregiving label = `gap_parental_only` − `gap_travel`;",
      "bundle = `parent_gap` − `gap_parental_only`.", "",
      "| model | parenthood net of disclosure | caregiving label net of interruption | family bundle on top of gap |",
      "| --- | --- | --- | --- |"]
for m in MODELS:
    d = placebo_decomposition(m)
    r = d[(d.level == "L0 name") & (d.group == "mothers")].iloc[0]
    L.append(f"| {SHORT[m]} | {r['parenthood (parent-personal)']:+.3f} | "
             f"{r['caregiving (gap_par-gap_travel)']:+.3f} | {r['bundle (parent_gap-gap_par)']:+.3f} |")

L += ["", "## §8.1 Direct gender contrasts — P(woman chosen) vs the man in the same prompt", "",
      "parity = .50. `gender_none` = childless woman vs childless man; `gender_parent` = mother vs father.", ""]
rows = []
for m in MODELS:
    gp = gender_preference(m)
    pw = gp[gp["stat"] == "P(woman chosen)"]
    for _, r in pw.iterrows():
        rows.append({"model": SHORT[m], "contrast": r["source"].split()[1], "level": r["level"], "P(woman)": r["value"]})
L.append(pd.DataFrame(rows).pivot(index=["contrast", "level"], columns="model").to_markdown())

L += ["", "## §8.6 Abstention — salary withholding (E1 women), by cue level", ""]
for m in MODELS:
    a = abstention(m)
    L.append(f"**{SHORT[m]}**")
    L.append("")
    L.append(a.to_markdown())
    L.append("")

L += ["## §8.7 Drift anchors (phase-3 L0 minus main-run interview rate, O20)", "",
      "| model | mean delta | range |", "| --- | --- | --- |"]
for m in MODELS:
    d = drift(m)
    L.append(f"| {SHORT[m]} | {d['delta'].mean():+.3f} | [{d['delta'].min():+.3f}, {d['delta'].max():+.3f}] |")

L += ["", "## Headline cross-model findings", "",
      "1. **The caregiving label does nothing — everywhere.** `gap_parental_only` − `gap_travel`",
      "   is +.01 to +.07 in all four models: an 8-month interruption costs the same whether it",
      "   is labeled *Parental leave* or *Career break — extended travel*. The damage lives in the",
      "   interruption itself (+ the family bundle: −.11 to −.24 on top).",
      "2. **Cue-level invariance (penalty is not about gender information) holds for DeepSeek,",
      "   Luna and Qwen.** Haiku is the exception: its plain-parent penalty *softens* when gender",
      "   is explicit (.275 L0-O8 → .335 L1 → .365 L2 vs .281 blind) — explicit gender partially",
      "   offsets its parent penalty in pairs.",
      "3. **Direct gender preference diverges sharply by vendor.** Qwen is at parity (.49–.51 at",
      "   every level). DeepSeek shows a small stable pro-woman tilt (+1.5–4.7pp). Luna's",
      "   pro-woman preference explodes with explicit gender (.52 L0 → .59/.65 L1 mothers-vs-",
      "   fathers). Haiku flips *against* mothers with explicit gender (.54 L0 → .47 L2).",
      "4. **Haiku's pregnancy abstention increases with explicit gender**: withholding 18.2%",
      "   (names only) → 27.5% (name+field) → 25.7% (initial+field). Explicit gender does not",
      "   trigger abstention in any other model (≤1.8% everywhere).",
      "5. **Drift is mild and uniform**: +1.1 to +3.5pp interview-rate anchors, all four models.",
      "",]

if __name__ == "__main__":
    text = "\n".join(L) + "\n"
    from audit.config import ROOT

    out = ROOT / "docs" / "phase3" / "CROSS_MODEL.md"
    out.write_text(text)
    print(f"wrote {out} ({len(text.splitlines())} lines)")
